{"command": "cat > /prediction.json << 'JSONEOF'
{
    "vllm/model_executor/layers/quantization/awq_triton.py": {
        "awq_dequantize_kernel": "@triton.jit\ndef awq_dequantize_kernel(\n        qweight_ptr,  # quantized matrix\n        scales_ptr,  # scales, per group\n        zeros_ptr,  # zeros, per group\n        group_size,  # Should always be one of the supported group sizes\n        result_ptr,  # Output matrix\n        num_cols,  # input num cols in qweight\n        num_rows,  # input num rows in qweight\n        BLOCK_SIZE_X: tl.constexpr,\n        BLOCK_SIZE_Y: tl.constexpr):\n    # Setup the pids.\n    pid_x = tl.program_id(axis=0)\n    pid_y = tl.program_id(axis=1)\n\n    # Compute offsets and masks for qweight_ptr.\n    offsets_y = pid_y * BLOCK_SIZE_Y + tl.arange(0, BLOCK_SIZE_Y)\n    offsets_x = pid_x * BLOCK_SIZE_X + tl.arange(0, BLOCK_SIZE_X * 8) // 8\n    offsets = num_cols * offsets_y[:, None] + offsets_x[None, :]\n\n    masks_y = offsets_y < num_rows\n    masks_x = offsets_x < num_cols\n    masks = masks_y[:, None] & masks_x[None, :]\n\n    # Compute offsets and masks for result output ptr.\n    result_offsets_y = pid_y * BLOCK_SIZE_Y + tl.arange(0, BLOCK_SIZE_Y)\n    result_offsets_x = pid_x * BLOCK_SIZE_X * 8 + tl.arange(0, BLOCK_SIZE_X * 8)\n    result_offsets = (8 * num_cols * result_offsets_y[:, None] +\n                      result_offsets_x[None, :])\n\n    result_masks_y = result_offsets_y < num_rows\n    result_masks_x = result_offsets_x < num_cols * 8\n    result_masks = result_masks_y[:, None] & result_masks_x[None, :]\n\n    # Load the weights.\n    iweights = tl.load(qweight_ptr + offsets, masks)\n\n    # Create reverse AWQ order as tensor: [0, 4, 1, 5, 2, 6, 3, 7]\n    # that will map given indices to the correct order.\n    reverse_awq_order_tensor = ((tl.arange(0, 2) * 4)[None, :] +\n                                tl.arange(0, 4)[:, None]).reshape(8)\n\n    # Use this to compute a set of shifts that can be used to unpack and\n    # reorder the values in iweights and zeros.\n    shifts = reverse_awq_order_tensor * 4\n    shifts = tl.broadcast_to(shifts[None, :], (BLOCK_SIZE_Y * BLOCK_SIZE_X, 8))\n    shifts = tl.reshape(shifts, (BLOCK_SIZE_Y, BLOCK_SIZE_X * 8))\n\n    # Unpack and reorder: shift out the correct 4-bit value and mask.\n    iweights = (iweights >> shifts) & 0xF\n\n    # Compute group index for this block - load zeros/scales once per group\n    group_start_y = pid_y * BLOCK_SIZE_Y\n    group_idx_y = group_start_y // group_size\n    \n    # Compute zero offsets - load once per group and broadcast\n    zero_offsets_x = pid_x * BLOCK_SIZE_X + tl.arange(0, BLOCK_SIZE_X * 8) // 8\n    zero_base_offset = group_idx_y * num_cols\n    zero_offsets = zero_base_offset + zero_offsets_x[None, :]\n    \n    # Load zeros for the entire group row\n    zero_col_mask = zero_offsets_x < num_cols\n    zeros_full = tl.load(zeros_ptr + zero_offsets, zero_col_mask[None, :])\n    \n    # Unpack zeros using the same shifts\n    zeros = (zeros_full >> shifts) & 0xF\n\n    # Compute scale offsets - load once per group and broadcast\n    scale_offsets_x = pid_x * BLOCK_SIZE_X * 8 + tl.arange(0, BLOCK_SIZE_X * 8)\n    scale_base_offset = group_idx_y * num_cols * 8\n    scale_offsets = scale_base_offset + scale_offsets_x[None, :]\n    \n    # Load scales for the entire group row\n    scale_col_mask = scale_offsets_x < num_cols * 8\n    scales = tl.load(scales_ptr + scale_offsets, scale_col_mask[None, :])\n\n    # Dequantize.\n    iweights = (iweights - zeros) * scales\n    iweights = iweights.to(result_ptr.type.element_ty)\n\n    # Finally, store.\n    tl.store(result_ptr + result_offsets, iweights, result_masks)",
        "awq_gemm_kernel": "@triton.jit\ndef awq_gemm_kernel(a_ptr, b_ptr, c_ptr, zeros_ptr, scales_ptr, M, N, K,\n                    group_size, BLOCK_SIZE_M: tl.constexpr,\n                    BLOCK_SIZE_N: tl.constexpr, BLOCK_SIZE_K: tl.constexpr,\n                    SPLIT_K: tl.constexpr):\n    pid = tl.program_id(axis=0)\n    pid_z = tl.program_id(1)\n\n    num_pid_n = tl.cdiv(N, BLOCK_SIZE_N)\n\n    pid_m = pid // num_pid_n\n    pid_n = pid % num_pid_n\n\n    accumulator_dtype = c_ptr.type.element_ty\n\n    accumulator = tl.zeros((BLOCK_SIZE_M, BLOCK_SIZE_N),\n                           dtype=accumulator_dtype)\n\n    # Create reverse AWQ order as tensor: [0, 4, 1, 5, 2, 6, 3, 7]\n    # that will map given indices to the correct order.\n    reverse_awq_order_tensor = ((tl.arange(0, 2) * 4)[None, :] +\n                                tl.arange(0, 4)[:, None]).reshape(8)\n\n    # Create the necessary shifts to use to unpack.\n    shifts = reverse_awq_order_tensor * 4\n    shifts = tl.broadcast_to(shifts[None, :],\n                             (BLOCK_SIZE_K * (BLOCK_SIZE_N // 8), 8))\n    shifts = tl.reshape(shifts, (BLOCK_SIZE_K, BLOCK_SIZE_N))\n\n    # Offsets and masks.\n    offsets_am = pid_m * BLOCK_SIZE_M + tl.arange(0, BLOCK_SIZE_M)\n    masks_am = offsets_am < M\n\n    offsets_bn = (pid_n * (BLOCK_SIZE_N // 8) +\n                  tl.arange(0, BLOCK_SIZE_N) // 8)\n    masks_bn = offsets_bn < N // 8\n\n    offsets_zn = (pid_n * (BLOCK_SIZE_N // 8) +\n                  tl.arange(0, BLOCK_SIZE_N) // 8)\n    masks_zn = offsets_zn < N // 8\n\n    offsets_sn = pid_n * BLOCK_SIZE_N + tl.arange(0, BLOCK_SIZE_N)\n    masks_sn = offsets_sn < N\n\n    offsets_k = pid_z * BLOCK_SIZE_K + tl.arange(0, BLOCK_SIZE_K)\n    offsets_a = K * offsets_am[:, None] + offsets_k[None, :]\n    offsets_b = (N // 8) * offsets_k[:, None] + offsets_bn[None, :]\n\n    a_ptrs = a_ptr + offsets_a\n    b_ptrs = b_ptr + offsets_b\n\n    for k in range(0, tl.cdiv(K, BLOCK_SIZE_K * SPLIT_K)):\n        masks_k = offsets_k < K\n        masks_a = masks_am[:, None] & masks_k[None, :]\n        a = tl.load(a_ptrs, mask=masks_a)\n\n        masks_b = masks_k[:, None] & masks_bn[None, :]\n        b = tl.load(b_ptrs, mask=masks_b)\n\n        # Dequantize b - load group-level zeros/scales once per group\n        # Compute group index for this K block\n        k_start = BLOCK_SIZE_K * SPLIT_K * k + pid_z * BLOCK_SIZE_K\n        group_idx_k = k_start // group_size\n        \n        # Load zeros once per group and broadcast to full tile\n        zero_base_offset = group_idx_k * (N // 8)\n        zero_offsets = zero_base_offset + offsets_zn[None, :]\n        zeros_full = tl.load(zeros_ptr + zero_offsets, mask=masks_zn[None, :])\n        zeros = (zeros_full >> shifts) & 0xF\n\n        # Load scales once per group and broadcast to full tile\n        scale_base_offset = group_idx_k * N\n        scale_offsets = scale_base_offset + offsets_sn[None, :]\n        scales = tl.load(scales_ptr + scale_offsets, mask=masks_sn[None, :])\n\n        b = (b >> shifts) & 0xF\n        b = (b - zeros) * scales\n        b = b.to(c_ptr.type.element_ty)\n\n        # Accumulate results.\n        accumulator = tl.dot(a, b, accumulator, out_dtype=accumulator_dtype)\n\n        offsets_k += BLOCK_SIZE_K * SPLIT_K\n        a_ptrs += BLOCK_SIZE_K * SPLIT_K\n        b_ptrs += BLOCK_SIZE_K * SPLIT_K * (N // 8)\n\n    c = accumulator.to(c_ptr.type.element_ty)\n    offs_cm = pid_m * BLOCK_SIZE_M + tl.arange(0, BLOCK_SIZE_M)\n    offs_cn = pid_n * BLOCK_SIZE_N + tl.arange(0, BLOCK_SIZE_N)\n    c_ptrs = c_ptr + N * offs_cm[:, None] + offs_cn[None, :]\n    c_mask = (offs_cm[:, None] < M) & (offs_cn[None, :] < N)\n    if SPLIT_K == 1:\n        tl.store(c_ptrs, c, mask=c_mask)\n    else:\n        tl.atomic_add(c_ptrs, c, mask=c_mask)"
    }
}
JSONEOF"}

